CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS device_identity(id TEXT PRIMARY KEY, installation_id TEXT NOT NULL, account_id TEXT NOT NULL, label TEXT NOT NULL, boot_id TEXT NOT NULL, credential_ref TEXT, credential_generation INTEGER NOT NULL DEFAULT 0, connection_epoch INTEGER NOT NULL DEFAULT 0, relay TEXT, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS grants(id TEXT PRIMARY KEY, alias TEXT NOT NULL UNIQUE, revision INTEGER NOT NULL, root TEXT NOT NULL, dev TEXT NOT NULL, ino TEXT NOT NULL, access TEXT NOT NULL, policy TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS workspaces(id TEXT PRIMARY KEY, device_id TEXT NOT NULL, account_id TEXT NOT NULL, grant_id TEXT NOT NULL REFERENCES grants(id), grant_revision INTEGER NOT NULL, root TEXT NOT NULL, access TEXT NOT NULL, writer_epoch INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'open', expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS writer_leases(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id), domain TEXT NOT NULL, epoch INTEGER NOT NULL, operation_id TEXT, quiescent INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS operations(id TEXT PRIMARY KEY, account_id TEXT NOT NULL, device_id TEXT NOT NULL, workspace_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, capability TEXT NOT NULL, revision TEXT NOT NULL, state TEXT NOT NULL, parent_id TEXT, actor_epoch INTEGER, accepted_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deadline INTEGER NOT NULL, result TEXT, payload_expired INTEGER NOT NULL DEFAULT 0, UNIQUE(account_id,device_id,workspace_id,idempotency_key));
CREATE TABLE IF NOT EXISTS operation_events(seq INTEGER PRIMARY KEY AUTOINCREMENT, operation_id TEXT NOT NULL, at INTEGER NOT NULL, component TEXT NOT NULL, event TEXT NOT NULL, metadata TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS file_commits(id TEXT PRIMARY KEY, operation_id TEXT NOT NULL, root TEXT NOT NULL, path TEXT NOT NULL, before_sha TEXT, after_sha TEXT, stage_path TEXT, state TEXT NOT NULL, metadata TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, operation_id TEXT NOT NULL REFERENCES operations(id), workspace_id TEXT NOT NULL, kind TEXT NOT NULL, worker_id TEXT NOT NULL, boot_id TEXT NOT NULL, pid INTEGER, process_start TEXT, control_socket TEXT, control_secret_ref TEXT, state TEXT NOT NULL, deadline INTEGER NOT NULL, lease_deadline INTEGER NOT NULL, argv_hash TEXT, mutating INTEGER NOT NULL, exit_code INTEGER, signal TEXT, committed_end INTEGER NOT NULL DEFAULT 0, retained_start INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS job_output_segments(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), stream TEXT NOT NULL, start_offset INTEGER NOT NULL, end_offset INTEGER NOT NULL, path TEXT NOT NULL, sha256 TEXT NOT NULL, created_at INTEGER NOT NULL, evicted INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS output_range ON job_output_segments(job_id,start_offset);
CREATE TABLE IF NOT EXISTS artifacts(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, account_id TEXT NOT NULL, path TEXT NOT NULL, sha256 TEXT NOT NULL, bytes INTEGER NOT NULL, mime_type TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, pinned INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS result_outbox(id TEXT PRIMARY KEY, operation_id TEXT NOT NULL, payload TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt INTEGER NOT NULL DEFAULT 0, acknowledged INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, label TEXT NOT NULL, brief TEXT NOT NULL, plan TEXT NOT NULL, state TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS task_results(task_id TEXT NOT NULL REFERENCES tasks(id), version INTEGER NOT NULL, body TEXT NOT NULL, sha256 TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(task_id,version));
CREATE TABLE IF NOT EXISTS skill_roots(alias TEXT PRIMARY KEY, path TEXT NOT NULL, grant_id TEXT, enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS skill_snapshots(id TEXT NOT NULL, digest TEXT NOT NULL, manifest TEXT NOT NULL, content TEXT NOT NULL, created_at INTEGER NOT NULL, pinned INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(id,digest));
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, request_hash TEXT NOT NULL, scope TEXT NOT NULL, state TEXT NOT NULL, expires_at INTEGER NOT NULL, consumed_by TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS searches(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, operation_id TEXT NOT NULL, query TEXT NOT NULL, state TEXT NOT NULL, matches TEXT NOT NULL, errors TEXT NOT NULL, truncated INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS uploads(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, path TEXT NOT NULL, expected_sha TEXT, expected_output_sha TEXT NOT NULL, total_bytes INTEGER NOT NULL, committed_bytes INTEGER NOT NULL DEFAULT 0, stage_path TEXT NOT NULL, state TEXT NOT NULL, created_at INTEGER NOT NULL);
